pylon_temple.source:
export const envelope = [41, 26, 48];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 20; // Center X

  // ---------------------------------------------------------------------------
  // PALETTE RESOLUTION
  // ---------------------------------------------------------------------------
  const pStone = api.theme?.stone?.primary || "minecraft:sandstone";
  const pAccent = api.theme?.stone?.accent || "minecraft:chiseled_sandstone";
  const pCutStone = api.theme?.ground?.plinth || "minecraft:cut_sandstone";
  const pSmoothStone = api.theme?.ground?.pavement || "minecraft:smooth_sandstone";
  const pStairs = api.theme?.stone?.stairs || "minecraft:sandstone_stairs";
  const pSlab = api.theme?.stone?.slab || "minecraft:sandstone_slab";
  const pWall = api.theme?.stone?.wall || "minecraft:sandstone_wall";
  const pWoodPlanks = api.theme?.wood?.planks || "minecraft:birch_planks";
  const pWoodFence = api.theme?.wood?.fence || "minecraft:birch_fence";
  const pWoodLog = api.theme?.wood?.log || "minecraft:stripped_birch_log";
  const pWoodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:birch_trapdoor";
  const pRoofSolid = api.theme?.roof?.solid || "minecraft:smooth_sandstone";
  const pRoofSlab = api.theme?.roof?.slab || "minecraft:smooth_sandstone_slab";

  // Special thematic blocks
  const pGold = "minecraft:gold_block";
  const pLapis = "minecraft:lapis_block";
  const pRedTerracotta = "minecraft:red_terracotta";
  const pBrazier = "minecraft:campfire[lit=true]";
  const pLantern = "minecraft:lantern[hanging=false]";
  const pHangingLantern = "minecraft:lantern[hanging=true]";

  // ---------------------------------------------------------------------------
  // DRAWING HELPERS
  // ---------------------------------------------------------------------------
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function fill(x1, y1, z1, x2, y2, z2, block) {
    const minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
    const minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
    const minZ = Math.min(z1, z2), maxZ = Math.max(z1, z2);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  // Ground conformity: guarantees solid foundation from the seat plane / ground
  const occupiedColumns = new Uint8Array(W * D);
  function markOccupied(x, z) {
    if (x >= 0 && x < W && z >= 0 && z < D) {
      occupiedColumns[x * D + z] = 1;
    }
  }

  function fillFoundation(x1, z1, x2, z2, topY) {
    for (let x = x1; x <= x2; x++) {
      for (let z = z1; z <= z2; z++) {
        markOccupied(x, z);
        const groundH = api.heightAt(x, z);
        const startY = Math.min(topY, groundH);
        for (let y = startY; y <= topY; y++) {
          set(x, y, z, pCutStone);
        }
      }
    }
  }

  // ---------------------------------------------------------------------------
  // 1. FOUNDATIONS & SUB-FLOORS
  // ---------------------------------------------------------------------------
  // Entrance approach / Dromos foundation (Z: 0..3, X: 11..29)
  fillFoundation(11, 0, 29, 3, 1);
  // Main temple complex footprint foundation (Z: 4..47, X: 2..38)
  fillFoundation(2, 4, 38, 47, 1);
  // Hypostyle & Sanctuary raised sub-floor (Z: 33..47, X: 2..38)
  fillFoundation(2, 33, 38, 47, 2);

  // ---------------------------------------------------------------------------
  // 2. ENTRANCE APPROACH & GUARDIAN SPHINXES (Z: 0..3)
  // ---------------------------------------------------------------------------
  // Central Processional Ramp
  for (let x = 17; x <= 23; x++) {
    set(x, 0, 0, `${pStairs}[facing=south,half=bottom]`);
    set(x, 1, 1, pSmoothStone);
    set(x, 1, 2, pSmoothStone);
    set(x, 1, 3, pSmoothStone);
  }
  // Ramp Edging
  set(16, 1, 0, pCutStone);
  set(24, 1, 0, pCutStone);
  for (let z = 1; z <= 3; z++) {
    set(16, 1, z, pCutStone);
    set(24, 1, z, pCutStone);
  }

  // Guardian Sphinxes (Couchant lions facing North)
  function buildSphinx(startX) {
    // Plinth
    fill(startX, 1, 1, startX + 2, 1, 3, pCutStone);
    // Body (Recumbent lion)
    set(startX + 1, 2, 3, `${pStairs}[facing=north,half=bottom]`);
    set(startX + 1, 2, 2, pStone);
    set(startX, 2, 2, `${pStairs}[facing=east,half=bottom]`);
    set(startX + 2, 2, 2, `${pStairs}[facing=west,half=bottom]`);
    // Forepaws extending north
    set(startX, 2, 1, `${pStairs}[facing=south,half=bottom]`);
    set(startX + 2, 2, 1, `${pStairs}[facing=south,half=bottom]`);
    // Chest and Head
    set(startX + 1, 2, 1, pStone);
    set(startX + 1, 3, 1, pAccent); // Pharaonic face / nemes
    set(startX + 1, 4, 1, `${pStairs}[facing=north,half=bottom]`); // Crown
  }
  buildSphinx(12); // Left Sphinx
  buildSphinx(26); // Right Sphinx

  // ---------------------------------------------------------------------------
  // 3. MONUMENTAL BATTERED PYLON TOWERS (Z: 4..14, Y: 1..22)
  // ---------------------------------------------------------------------------
  // Helper for pylon battering (sloping walls inward as height increases)
  function getPylonBounds(y) {
    const zMin = 4 + Math.floor(y / 7);
    const zMax = 14 - Math.floor(y / 11);
    const leftXMin = 2 + Math.floor(y / 7);
    const leftXMax = 17;
    const rightXMin = 23;
    const rightXMax = 38 - Math.floor(y / 7);
    return { zMin, zMax, leftXMin, leftXMax, rightXMin, rightXMax };
  }

  // Construct battered pylon towers course by course
  for (let y = 1; y <= 21; y++) {
    const { zMin, zMax, leftXMin, leftXMax, rightXMin, rightXMax } = getPylonBounds(y);
    const bandBlock = (y === 6 || y === 12 || y === 18) ? pAccent : pStone;

    // LEFT PYLON
    for (let x = leftXMin; x <= leftXMax; x++) {
      for (let z = zMin; z <= zMax; z++) {
        // Hollow out interior vault & stairwell (Y: 2..19)
        const isInterior = (x >= 6 && x <= 14 && z >= 7 && z <= 11 && y >= 2 && y <= 19);
        if (isInterior) {
          // Interior stairs winding along walls
          const stairStep = (y - 2) % 16;
          let isStair = false;
          if (stairStep < 4 && z === 7 && x === 6 + stairStep) isStair = true;
          else if (stairStep >= 4 && stairStep < 8 && x === 14 && z === 7 + (stairStep - 4)) isStair = true;
          else if (stairStep >= 8 && stairStep < 12 && z === 11 && x === 14 - (stairStep - 8)) isStair = true;
          else if (stairStep >= 12 && x === 6 && z === 11 - (stairStep - 12)) isStair = true;

          if (isStair) {
            set(x, y, z, pCutStone);
          } else {
            set(x, y, z, "minecraft:air");
          }
        } else {
          set(x, y, z, bandBlock);
        }
      }
    }

    // RIGHT PYLON
    for (let x = rightXMin; x <= rightXMax; x++) {
      for (let z = zMin; z <= zMax; z++) {
        const isInterior = (x >= 26 && x <= 34 && z >= 7 && z <= 11 && y >= 2 && y <= 19);
        if (isInterior) {
          const stairStep = (y - 2) % 16;
          let isStair = false;
          if (stairStep < 4 && z === 7 && x === 34 - stairStep) isStair = true;
          else if (stairStep >= 4 && stairStep < 8 && x === 26 && z === 7 + (stairStep - 4)) isStair = true;
          else if (stairStep >= 8 && stairStep < 12 && z === 11 && x === 26 + (stairStep - 8)) isStair = true;
          else if (stairStep >= 12 && x === 34 && z === 11 - (stairStep - 12)) isStair = true;

          if (isStair) {
            set(x, y, z, pCutStone);
          } else {
            set(x, y, z, "minecraft:air");
          }
        } else {
          set(x, y, z, bandBlock);
        }
      }
    }
  }

  // Internal access doorways from the courtyard into pylon stairwells
  fill(10, 1, 14, 10, 3, 14, "minecraft:air"); // Left door
  fill(30, 1, 14, 30, 3, 14, "minecraft:air"); // Right door

  // Flagstaff Grooves and Tall Timber Masts on Facades
  const flagstaffX = [7, 13, 27, 33];
  flagstaffX.forEach((fx) => {
    // Flagstaff stone base socket
    set(fx, 1, 3, pAccent);

    // Carve vertical groove into pylon facade and place tall mast
    for (let y = 1; y <= 21; y++) {
      const { zMin } = getPylonBounds(y);
      set(fx, y, zMin, pAccent); // Recessed groove
      set(fx, y, zMin - 1, pWoodFence); // Tall wooden flag mast

      // Bronze/copper mounting brackets
      if (y === 6 || y === 12 || y === 18) {
        set(fx, y, zMin - 1, pAccent);
      }
    }

    // Flagstaff upper extension above pylon roof
    const topZ = getPylonBounds(21).zMin - 1;
    set(fx, 22, topZ, pWoodFence);
    set(fx, 23, topZ, pWoodFence);
    set(fx, 24, topZ, pWoodFence);
    set(fx, 25, topZ, pGold); // Gilded finial
    // Hanging ceremonial banner
    set(fx, 24, topZ - 1, pRedTerracotta);
    set(fx, 23, topZ - 1, pRedTerracotta);
  });

  // Cavetto Cornice at Pylon Summits (Y: 21..23)
  function buildCavettoCornice(minX, maxX, minZ, maxZ) {
    // Torus molding rim (Y: 21)
    for (let x = minX; x <= maxX; x++) {
      set(x, 21, minZ, pAccent);
      set(x, 21, maxZ, pAccent);
    }
    for (let z = minZ; z <= maxZ; z++) {
      set(minX, 21, z, pAccent);
      set(maxX, 21, z, pAccent);
    }

    // Flared Cavetto Overhang (Y: 22)
    for (let x = minX - 1; x <= maxX + 1; x++) {
      set(x, 22, minZ - 1, `${pStairs}[facing=north,half=top]`);
      set(x, 22, maxZ + 1, `${pStairs}[facing=south,half=top]`);
    }
    for (let z = minZ - 1; z <= maxZ + 1; z++) {
      set(minX - 1, 22, z, `${pStairs}[facing=west,half=top]`);
      set(maxX + 1, 22, z, `${pStairs}[facing=east,half=top]`);
    }
    // Solid corner caps
    set(minX - 1, 22, minZ - 1, pStone);
    set(maxX + 1, 22, minZ - 1, pStone);
    set(minX - 1, 22, maxZ + 1, pStone);
    set(maxX + 1, 22, maxZ + 1, pStone);

    // Roof Terrace Paving (Y: 21)
    fill(minX + 1, 21, minZ + 1, maxX - 1, maxZ - 1, pRoofSolid);
  }

  const topBounds = getPylonBounds(21);
  buildCavettoCornice(topBounds.leftXMin, topBounds.leftXMax, topBounds.zMin, topBounds.zMax);
  buildCavettoCornice(topBounds.rightXMin, topBounds.rightXMax, topBounds.zMin, topBounds.zMax);

  // ---------------------------------------------------------------------------
  // 4. CENTRAL GATEWAY PORTAL (X: 18..22, Z: 4..14)
  // ---------------------------------------------------------------------------
  // Portal Jambs & Gateway Passage
  fill(18, 1, 4, 18, 11, 14, pStone);
  fill(22, 1, 4, 22, 11, 14, pStone);
  // Clear open archway (width 3, height 8)
  fill(19, 1, 4, 21, 8, 14, "minecraft:air");
  // Floor in passage
  fill(19, 1, 4, 21, 1, 14, pSmoothStone);

  // Arch Springing & Lintel
  for (let z = 4; z <= 14; z++) {
    set(19, 8, z, `${pStairs}[facing=east,half=top]`);
    set(20, 8, z, `${pSlab}[type=top]`);
    set(21, 8, z, `${pStairs}[facing=west,half=top]`);
    fill(19, 9, z, 21, 11, z, pStone);
  }

  // Winged Sun Disk Relief Frieze on Facade (Z: 4, Y: 10..11)
  set(19, 10, 4, pAccent);
  set(20, 10, 4, pGold); // Solar disk
  set(21, 10, 4, pAccent);
  set(20, 11, 4, pLapis);

  // Portal Cavetto Cornice (Y: 12..13)
  for (let x = 17; x <= 23; x++) {
    set(x, 12, 3, `${pStairs}[facing=north,half=top]`);
    set(x, 13, 3, pRoofSlab);
    set(x, 12, 14, `${pStairs}[facing=south,half=top]`);
    set(x, 13, 14, pRoofSlab);
  }
  fill(18, 12, 4, 22, 12, 13, pStone);

  // ---------------------------------------------------------------------------
  // 5. INNER PERISTYLE COURTYARD (Z: 14..33)
  // ---------------------------------------------------------------------------
  // Courtyard Outer Flank Walls
  fill(2, 1, 14, 3, 9, 33, pStone);
  fill(37, 1, 14, 38, 9, 33, pStone);
  // Wall decorative bands & copings
  for (let z = 14; z <= 33; z++) {
    set(3, 5, z, pAccent);
    set(37, 5, z, pAccent);
    set(2, 10, z, `${pStairs}[facing=west,half=bottom]`);
    set(3, 10, z, `${pStairs}[facing=east,half=bottom]`);
    set(37, 10, z, `${pStairs}[facing=west,half=bottom]`);
    set(38, 10, z, `${pStairs}[facing=east,half=bottom]`);
  }

  // Courtyard Floor Paving (Y: 1)
  fill(4, 1, 15, 36, 1, 32, pSmoothStone);
  // Processional central axial pathway
  fill(19, 1, 15, 21, 1, 32, pCutStone);

  // Papyrus Colonnades (Porticos on East & West flanks)
  function buildPapyrusColumn(colX, colZ) {
    // Plinth base
    set(colX, 1, colZ, pAccent);
    // Column shaft
    fill(colX, 2, colZ, colX, 6, colZ, pStone);
    // Papyrus Open Bud Capital (Y: 7)
    set(colX, 7, colZ, pAccent);
    set(colX, 7, colZ - 1, `${pStairs}[facing=north,half=top]`);
    set(colX, 7, colZ + 1, `${pStairs}[facing=south,half=top]`);
    set(colX - 1, 7, colZ, `${pStairs}[facing=west,half=top]`);
    set(colX + 1, 7, colZ, `${pStairs}[facing=east,half=top]`);
  }

  const colZPositions = [17, 21, 25, 29];
  colZPositions.forEach((cz) => {
    buildPapyrusColumn(10, cz); // West colonnade row
    buildPapyrusColumn(30, cz); // East colonnade row
  });

  // Colonnade Architraves & Portico Roof (Y: 8..9)
  // West portico
  fill(10, 8, 15, 10, 8, 32, pStone);
  for (let cz of colZPositions) {
    fill(4, 8, cz, 10, 8, cz, pStone);
  }
  fill(4, 9, 15, 10, 9, 32, pRoofSlab);

  // East portico
  fill(30, 8, 15, 30, 8, 32, pStone);
  for (let cz of colZPositions) {
    fill(30, 8, cz, 36, 8, cz, pStone);
  }
  fill(30, 9, 15, 36, 9, 32, pRoofSlab);

  // Central Sun Altar / Barque Dais (X: 19..21, Z: 23..25)
  fill(18, 1, 22, 22, 1, 26, pCutStone);
  fill(19, 2, 23, 21, 2, 25, pAccent);
  // Altar steps
  set(20, 2, 22, `${pStairs}[facing=south,half=bottom]`);
  set(20, 2, 26, `${pStairs}[facing=north,half=bottom]`);
  set(18, 2, 24, `${pStairs}[facing=east,half=bottom]`);
  set(22, 2, 24, `${pStairs}[facing=west,half=bottom]`);
  // Offering Table & Sacred Brazier
  set(20, 3, 24, pGold);
  set(20, 4, 24, pBrazier);

  // ---------------------------------------------------------------------------
  // 6. HYPOSTYLE HALL & VESTIBULE (Z: 33..41)
  // ---------------------------------------------------------------------------
  // Raised Hypostyle Floor at Y: 2
  fill(4, 2, 33, 36, 2, 41, pSmoothStone);
  // Entrance steps up to Hypostyle Hall
  for (let x = 18; x <= 22; x++) {
    set(x, 2, 32, `${pStairs}[facing=south,half=bottom]`);
  }

  // Intercolumnar Screen Facade (Z: 33)
  fill(4, 2, 33, 17, 5, 33, pStone);
  fill(23, 2, 33, 36, 5, 33, pStone);
  for (let x = 4; x <= 17; x++) set(x, 5, 33, pAccent);
  for (let x = 23; x <= 36; x++) set(x, 5, 33, pAccent);
  // Screen facade doorway
  fill(18, 2, 33, 22, 7, 33, "minecraft:air");
  set(18, 7, 33, `${pStairs}[facing=east,half=top]`);
  set(22, 7, 33, `${pStairs}[facing=west,half=top]`);
  fill(18, 8, 33, 22, 8, 33, pStone);

  // Outer Flank Walls for Hypostyle
  fill(2, 2, 34, 3, 10, 41, pStone);
  fill(37, 2, 34, 38, 10, 41, pStone);

  // Massive Hypostyle Columns (Papyrus Bundles)
  const hypostyleColumns = [
    [8, 36], [14, 36], [26, 36], [32, 36],
    [8, 40], [14, 40], [26, 40], [32, 40],
  ];

  hypostyleColumns.forEach(([hx, hz]) => {
    // Plinth
    set(hx, 2, hz, pAccent);
    // Shaft
    fill(hx, 3, hz, hx, 7, hz, pStone);
    // Bud capital
    set(hx, 8, hz, pAccent);
    set(hx, 8, hz - 1, `${pStairs}[facing=north,half=top]`);
    set(hx, 8, hz + 1, `${pStairs}[facing=south,half=top]`);
    set(hx - 1, 8, hz, `${pStairs}[facing=west,half=top]`);
    set(hx + 1, 8, hz, `${pStairs}[facing=east,half=top]`);
  });

  // Hypostyle Architraves (Y: 9)
  for (let z of [36, 40]) {
    fill(4, 9, z, 36, 9, z, pStone);
  }
  for (let x of [8, 14, 26, 32]) {
    fill(x, 9, 33, x, 9, 41, pStone);
  }

  // Side Aisles Lower Roof (Y: 10)
  fill(4, 10, 33, 13, 10, 41, pRoofSolid);
  fill(27, 10, 33, 36, 10, 41, pRoofSolid);

  // Central Nave Clerestory & Raised Roof (Y: 11..13)
  // Clerestory stone lattice window grilles
  for (let z = 34; z <= 41; z++) {
    set(13, 11, z, pWall);
    set(13, 12, z, pStone);
    set(27, 11, z, pWall);
    set(27, 12, z, pStone);
  }
  // Central Nave high roof
  fill(13, 13, 33, 27, 13, 41, pRoofSolid);

  // ---------------------------------------------------------------------------
  // 7. HOLY OF HOLIES / INNER NAOS SANCTUARY (Z: 42..47)
  // ---------------------------------------------------------------------------
  // Sanctuary Floor at Y: 2
  fill(4, 2, 42, 36, 2, 46, pSmoothStone);

  // Rear Enclosure Wall
  fill(2, 2, 46, 38, 10, 47, pStone);

  // Sanctuary Partition Walls (Enclosing central Naos chamber)
  fill(17, 2, 42, 17, 10, 46, pStone);
  fill(23, 2, 42, 23, 10, 46, pStone);
  // Front partition wall of Sanctuary
  fill(18, 2, 42, 22, 10, 42, pStone);
  // Doorway into Inner Sanctuary (X: 19..21, Y: 2..5)
  fill(19, 2, 42, 21, 5, 42, "minecraft:air");
  set(19, 5, 42, `${pStairs}[facing=east,half=top]`);
  set(21, 5, 42, `${pStairs}[facing=west,half=top]`);

  // Roof over Sanctuary and Treasuries (Y: 10)
  fill(4, 10, 42, 36, 10, 46, pRoofSolid);

  // The Holy Naos Shrine (X: 19..21, Z: 44..45)
  fill(19, 2, 44, 21, 2, 45, pCutStone);
  // Gilded Shrine Casing
  fill(19, 3, 44, 21, 5, 45, pAccent);
  // Shrine inner niche with Sacred Deity Relic
  set(20, 3, 44, "minecraft:air");
  set(20, 4, 44, "minecraft:air");
  set(20, 3, 45, pGold); // Golden barque / idol
  set(20, 4, 45, pLapis);

  // Side Treasuries Doorways from Hypostyle Hall
  fill(10, 2, 41, 11, 4, 41, "minecraft:air"); // Left treasury entrance
  fill(29, 2, 41, 30, 4, 41, "minecraft:air"); // Right treasury entrance

  // ---------------------------------------------------------------------------
  // 8. ATMOSPHERIC DETAILS & TEMPLE LIGHTING
  // ---------------------------------------------------------------------------
  // Braziers flanking the sanctuary portal
  set(16, 2, 41, pBrazier);
  set(24, 2, 41, pBrazier);

  // Sanctuary inner hanging lanterns
  set(18, 6, 44, pHangingLantern);
  set(22, 6, 44, pHangingLantern);

  // Courtyard portico shaded lanterns
  for (let cz of [19, 27]) {
    set(6, 8, cz, pHangingLantern);
    set(34, 8, cz, pHangingLantern);
  }

  // ---------------------------------------------------------------------------
  // 9. SOLID GROUND CONFORMITY PASS (Rule 6)
  // ---------------------------------------------------------------------------
  // Scan all columns in envelope: wherever we built structure, extend downward
  // solid to the real terrain height (handles cliffs, slopes, river banks, seabed).
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (occupiedColumns[x * D + z]) {
        const gh = api.heightAt(x, z);
        if (gh < 0) {
          for (let y = gh; y < 0; y++) {
            set(x, y, z, pCutStone);
          }
        }
      }
    }
  }

  // ---------------------------------------------------------------------------
  // RETURN CONTRACT
  // ---------------------------------------------------------------------------
  return {
    name: "pylon_temple",
    seatY: 0,
    anchors: {
      front: [cx, 1, 0],       // Monument looks out to North (-Z)
      door: [cx, 1, 4],        // Main Pylon gateway entrance
      altar: [cx, 2, 24],      // Courtyard sun altar
      sanctuary: [cx, 2, 44],  // Holy Naos sacred barque shrine
    },
    interiors: [
      { min: [6, 2, 7], max: [14, 18, 11], kind: "vault" },       // Left Pylon Vault
      { min: [26, 2, 7], max: [34, 18, 11], kind: "vault" },      // Right Pylon Vault
      { min: [5, 2, 34], max: [35, 9, 41], kind: "hall" },        // Hypostyle Hall
      { min: [18, 2, 43], max: [22, 9, 45], kind: "vault" },      // Holy of Holies Sanctuary
      { min: [5, 2, 42], max: [16, 9, 45], kind: "quarters" },    // West Treasury
      { min: [24, 2, 42], max: [35, 9, 45], kind: "quarters" },   // East Treasury
    ],
  };
}
